.bar-row{display:grid;grid-template-columns:90px 1fr 30px;align-items:center;gap:8px}.bar-row>span{overflow:hidden;color:var(--ink-soft);font-size:9.5px;font-weight:800;text-overflow:ellipsis;white-space:nowrap}.bar-row>div{height:8px;overflow:hidden;border-radius:99px;background:var(--surface-2)}.bar-row i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,var(--primary),#0ea5e9)}.bar-row b{color:var(--ink);font-size:10px;text-align:end}.table-scroll{overflow:auto}.tbl{min-width:520px}.tbl b{color:var(--ink);font-size:10.5px}.tbl small{display:block;margin-top:2px;color:var(--ink-faint);font-size:8.5px}.positive{color:var(--success)}.negative{color:var(--danger)}.rate{display:block;position:relative;overflow:hidden;min-width:70px;padding:3px 6px;border-radius:99px;color:var(--ink);background:var(--surface-2);font-size:9px;font-weight:850;text-align:center}.rate i{position:absolute;z-index:0;inset-block:0;inset-inline-start:0;background:var(--success-tint)}.rate{isolation:isolate}.rate::first-letter{position:relative}@media(max-width:1060px){.analysis-grid,.two-tables{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(4,minmax(140px,1fr));overflow:auto;padding-bottom:3px}.kpi{min-width:140px}}@media(max-width:620px){.page-heading{align-items:start;flex-direction:column}.date-filter{width:100%;display:grid;grid-template-columns:1fr 1fr}.date-filter .primary{grid-column:1/-1}.kpis{grid-template-columns:repeat(2,minmax(0,1fr));overflow:visible}.kpi{min-width:0}.analysis-grid,.two-tables{gap:12px}}
</style>
